// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');
const loadPlayfairDisplay = makeLoadFont('PlayfairDisplay');

const { fontFamily: robotoMono } = loadRobotoMono();
const { fontFamily: playfairDisplay } = loadPlayfairDisplay();

// -----------------------------------------------------------------------------
// SCHEMA
// -----------------------------------------------------------------------------


export type MacintoshTimelineProps = Record<string, any>;

// -----------------------------------------------------------------------------
// MAIN COMPONENT
// -----------------------------------------------------------------------------
const MacintoshTimeline: React.FC<MacintoshTimelineProps> = ({
  backgroundColor = "#090b0e",
  lineColor = "#ffffff",
  accentColor = "#ffc800",
  accentLineWidth = 35,
  durationInSeconds = 10,
  mainHeadline = "Not a\nmarket wall.",
  legendText = "market demand",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Timing constants
  const impactFrame = 60; // 2 seconds in at 30fps

  // Line Draw Animation (0-60 frames)
  const pathTotalLength = 2000; // Approximate length of the jagged path
  const lineDrawProgress = interpolate(frame, [0, impactFrame], [pathTotalLength, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Impact Animations (60+ frames)
  const isImpacted = frame >= impactFrame;
  const impactSpring = spring({ frame: frame - impactFrame, fps, config: { damping: 12, mass: 0.5 } });
  
  // Shard & Crack timings
  const crackReveal = interpolate(frame, [impactFrame, impactFrame + 10], [100, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const pulseOpacity = interpolate(frame, [impactFrame, impactFrame + 15, impactFrame + 40], [0, 0.8, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  // Coordinates
  const impactX = 1300;
  const impactY = 380;

  // Hardcoded jagged path leading exactly to impactX, impactY
  const graphPath = `
    M -50 950 
    L 50 940 L 100 945 L 150 910 L 200 920 L 250 880 L 300 890 
    L 350 840 L 400 850 L 450 780 L 500 800 L 550 710 L 600 730 
    L 650 640 L 700 660 L 750 550 L 800 580 L 850 470 L 900 520 
    L 950 430 L 1000 460 L 1050 350 L 1100 390 L 1150 280 L 1200 320 
    L 1250 360 L 1280 375 L ${impactX} ${impactY}
  `;

  // Grid / Axis logic
  const yAxisTicks = [
    { label: "120", y: 180 },
    { label: "100", y: impactY },
    { label: "80", y: 580 },
    { label: "60", y: 780 },
    { label: "40", y: 980 },
  ];

  // Pre-calculated glass shards (deterministic, no Math.random)
  const shards = [
    { id: 1, x: -30, y: -20, vx: -3, vy: -1.5, rot: -45 },
    { id: 2, x: -50, y: 10, vx: -4, vy: 0.5, rot: 60 },
    { id: 3, x: -20, y: 30, vx: -2, vy: 2, rot: 120 },
    { id: 4, x: -60, y: -10, vx: -5, vy: -0.2, rot: -20 },
    { id: 5, x: -40, y: -40, vx: -2.5, vy: -3, rot: 80 },
    { id: 6, x: -10, y: 15, vx: -1, vy: 1, rot: 30 },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor, overflow: "hidden", transition: "none" }}>
      
      {/* BACKGROUND FLOOR GRADIENT */}
      <div style={{
        position: "absolute", bottom: 0, left: 0, width: "100%", height: 300,
        background: `linear-gradient(to top, rgba(255,255,255,0.05) 0%, transparent 100%)`,
        zIndex: 0
      }} />

      {/* SVG LAYER: Grid, Lines, Wall, Cracks */}
      <svg width="1920" height="1080" style={{ position: "absolute", inset: 0, zIndex: 10 }}>
        <defs>
          <filter id="glowBlur" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="8" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
          <filter id="impactGlow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="15" result="blur" />
          </filter>
        </defs>

        {/* BACKGROUND GRID LINES */}
        <g stroke="rgba(255,255,255,0.08)" strokeWidth="1" strokeDasharray="2 4">
          <line x1="800" y1="0" x2="800" y2="1080" />
          <line x1="1050" y1="0" x2="1050" y2="1080" />
          <line x1="1300" y1="0" x2="1300" y2="1080" />
          <line x1="1550" y1="0" x2="1550" y2="1080" />
          <line x1="1800" y1="0" x2="1800" y2="1080" />
          {yAxisTicks.map((tick) => (
            <line key={tick.label} x1="1300" y1={tick.y} x2="1800" y2={tick.y} />
          ))}
        </g>

        {/* GLASS WALL - BACKGROUND PANELS */}
        <g>
          {/* Back Edge (Inside depth) */}
          <polygon points="1300,100 1300,950 1700,850 1700,200" fill="rgba(255,255,255,0.02)" />
        </g>

        {/* MAIN GRAPH LINE */}
        {/* Glow Layer */}
        <path 
          d={graphPath} 
          fill="none" 
          stroke={lineColor} 
          strokeWidth="6" 
          strokeLinejoin="miter"
          strokeDasharray={pathTotalLength}
          strokeDashoffset={lineDrawProgress}
          filter="url(#glowBlur)"
          opacity={0.6}
        />
        {/* Core Line Layer */}
        <path 
          d={graphPath} 
          fill="none" 
          stroke={lineColor} 
          strokeWidth="3" 
          strokeLinejoin="miter"
          strokeDasharray={pathTotalLength}
          strokeDashoffset={lineDrawProgress}
        />

        {/* IMPACT PULSE GLOW */}
        {isImpacted && (
          <circle 
            cx={impactX} 
            cy={impactY} 
            r={interpolate(impactSpring, [0, 1], [0, 40])} 
            fill={lineColor} 
            opacity={pulseOpacity}
            filter="url(#impactGlow)"
          />
        )}

        {/* GLASS WALL - FRONT PANELS & EDGES */}
        <g>
          {/* Main Front Face */}
          <polygon 
            points="1300,80 1300,980 1700,850 1700,150" 
            fill="rgba(255,255,255,0.03)" 
            stroke="rgba(255,255,255,0.3)" 
            strokeWidth="1.5" 
          />
          {/* Thick Left Edge */}
          <polygon 
            points="1285,90 1300,80 1300,980 1285,990" 
            fill="rgba(255,255,255,0.15)" 
            stroke={lineColor} 
            strokeWidth="2" 
            strokeLinejoin="round"
          />
          {/* Highlights on Edge */}
          <line x1="1285" y1="90" x2="1285" y2="990" stroke="rgba(255,255,255,0.8)" strokeWidth="1" />
        </g>

        {/* CRACKS & SHATTERS (Triggers on Impact) */}
        {isImpacted && (
          <g>
            {/* Crack lines on the glass */}
            <g stroke={lineColor} strokeWidth="1" strokeLinecap="round" strokeLinejoin="round" fill="none">
              <path d={`M ${impactX} ${impactY} L 1320 340 L 1340 330`} strokeDasharray="100" strokeDashoffset={crackReveal} />
              <path d={`M ${impactX} ${impactY} L 1330 390 L 1360 410`} strokeDasharray="100" strokeDashoffset={crackReveal} />
              <path d={`M ${impactX} ${impactY} L 1315 440 L 1325 470`} strokeDasharray="100" strokeDashoffset={crackReveal} />
              <path d={`M ${impactX} ${impactY} L 1290 310`} strokeDasharray="100" strokeDashoffset={crackReveal} />
              <path d={`M ${impactX} ${impactY} L 1280 430`} strokeDasharray="100" strokeDashoffset={crackReveal} />
              <path d={`M ${impactX} ${impactY} L 1350 360`} strokeDasharray="100" strokeDashoffset={crackReveal} />
            </g>

            {/* Flying Shards */}
            {shards.map((shard) => {
              const progress = interpolate(frame, [impactFrame, impactFrame + 30], [0, 1], { extrapolateRight: "clamp" });
              const currentX = impactX + shard.x * progress + (shard.vx * progress * 20);
              const currentY = impactY + shard.y * progress + (shard.vy * progress * 20) + (progress * progress * 10); // slight gravity
              const currentRot = shard.rot * progress * 2;
              const opacity = interpolate(progress, [0.5, 1], [1, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
              
              return (
                <polygon
                  key={shard.id}
                  points="-4,-2 4,-3 6,3 -2,4"
                  fill="rgba(255,255,255,0.8)"
                  stroke={lineColor}
                  strokeWidth="0.5"
                  opacity={opacity}
                  transform={`translate(${currentX}, ${currentY}) rotate(${currentRot})`}
                />
              );
            })}
          </g>
        )}
      </svg>


      {/* HTML LAYER: Typography & UI Elements */}
      <div style={{ position: "absolute", inset: 0, zIndex: 20, pointerEvents: "none" }}>
        
        {/* MAIN HEADLINE */}
        <div style={{
          position: "absolute", top: 220, left: 140,
          fontFamily: playfairDisplay, color: lineColor,
          fontSize: 100, fontWeight: 700, lineHeight: 1.1,
          letterSpacing: "-1px"
        }}>
          {mainHeadline.split('\n').map((line, i) => (
            <div key={i} style={{ position: "relative", display: "inline-block", width: "100%" }}>
              {line}
              {/* Add underline only to the first line (simulating the "Not a" underline from the reference) */}
              {i === 0 && (
                <div style={{
                  position: "absolute", bottom: 10, left: 0, 
                  height: 4, width: `${accentLineWidth}%`, backgroundColor: accentColor
                }} />
              )}
            </div>
          ))}
        </div>

        {/* BOTTOM LEFT LEGEND */}
        <div style={{
          position: "absolute", bottom: 120, left: 140,
          display: "flex", alignItems: "center", gap: 15,
          fontFamily: robotoMono, fontSize: 16, color: "rgba(255,255,255,0.6)"
        }}>
          <div style={{ width: 40, height: 2, backgroundColor: lineColor }} />
          <span>{legendText}</span>
        </div>

        {/* RIGHT Y-AXIS LABELS */}
        <div style={{
          position: "absolute", top: 0, right: 60, height: "100%",
          display: "flex", flexDirection: "column",
          fontFamily: robotoMono, fontSize: 16, color: "rgba(255,255,255,0.5)"
        }}>
          {yAxisTicks.map((tick) => (
            <div key={tick.label} style={{
              position: "absolute", top: tick.y, right: 0,
              transform: "translateY(-50%)", display: "flex", alignItems: "center", gap: 15
            }}>
              {/* Highlight Arrow for the Impact Tick */}
              {tick.label === "100" && (
                <svg width="12" height="12" viewBox="0 0 12 12" style={{ fill: accentColor }}>
                  <polygon points="12,0 0,6 12,12" />
                </svg>
              )}
              <div style={{ width: 10, height: 1, backgroundColor: "rgba(255,255,255,0.3)" }} />
              <span style={{ 
                color: tick.label === "100" ? "rgba(255,255,255,0.8)" : "rgba(255,255,255,0.5)",
                fontWeight: tick.label === "100" ? "bold" : "normal"
              }}>
                {tick.label}
              </span>
            </div>
          ))}
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default MacintoshTimeline;